class RateLimiter {
  private readonly buckets = new Map<string, RateLimitBucket>();
  private readonly capacity: number;
  private readonly refillPerSec: number;

  constructor(opts: RateLimitOptions) {
    if (opts.capacity <= 0) throw new Error("capacity must be > 0");
    if (opts.refillPerSec <= 0) throw new Error("refillPerSec must be > 0");
    this.capacity = opts.capacity;
    this.refillPerSec = opts.refillPerSec;
  }

  consume(key: string, cost = 1): boolean {
    const now = Date.now();
    const bucket = this.buckets.get(key) ?? this.makeBucket(now);
    const elapsedSec = (now - bucket.lastRefillMs) / 1000;
    const refilled = Math.min(
      bucket.capacity,
      bucket.tokens + elapsedSec * bucket.refillPerSec,
    );
    bucket.tokens = refilled;
    bucket.lastRefillMs = now;

    if (bucket.tokens < cost) {
      this.buckets.set(key, bucket);
      return false;
    }
    bucket.tokens -= cost;
    this.buckets.set(key, bucket);
    return true;
  }

  remaining(key: string): number {
    const bucket = this.buckets.get(key);
    if (!bucket) return this.capacity;
    return Math.floor(bucket.tokens);
  }

  reset(key: string): void {
    this.buckets.delete(key);
  }

  private makeBucket(now: number): RateLimitBucket {
    return {
      tokens: this.capacity,
      capacity: this.capacity,
      refillPerSec: this.refillPerSec,
      lastRefillMs: now,
    };
  }
}

export function createLimiter(opts: RateLimitOptions): RateLimiter {
  return new RateLimiter(opts);
}

export function exponentialBackoff(attempt: number, baseMs = 250, capMs = 30_000): number {
  const exp = Math.min(capMs, baseMs * 2 ** attempt);
  const jitter = Math.random() * exp * 0.25;
  return Math.floor(exp - jitter);
}

